            string coinKey=MatchReplayAssets.Current.particleKeys.First(k=>k.StartsWith("TableSet07\t",StringComparison.Ordinal)&&k.EndsWith("/Coin_LightUp|Flare_Glint",StringComparison.Ordinal));var pooledCoin=new GameObject("CoinLightUp",typeof(ParticleSystem));SceneManager.MoveGameObjectToScene(pooledCoin,scene);scene.name="TableSet07";pooledCoin.GetComponent<ParticleSystemRenderer>().sharedMaterial=MatchReplayAssets.Current.Particle(coinKey).GetComponent<ParticleSystemRenderer>().sharedMaterial;Check(MatchReplayAssets.Current.FindParticleKey(pooledCoin.GetComponent<ParticleSystem>())==coinKey,"Pooled particle names normalize separators and preserve the scene-specific template");UnityEngine.Object.DestroyImmediate(pooledCoin);
