            var particleTemplate=MatchReplayAssets.Current.Particle(particleKey);var particleGo=UnityEngine.Object.Instantiate(particleTemplate);SceneManager.MoveGameObjectToScene(particleGo,scene);particleGo.name=particleTemplate.name;particleGo.layer=30;
