            var particle=particleGo.GetComponent<ParticleSystem>();particle.Stop(false,ParticleSystemStopBehavior.StopEmittingAndClear);var trigger=particle.trigger;trigger.enabled=true; // Exercise the exact-buffer fallback.
            var particleMain=particle.main;particleMain.duration=2;particleMain.loop=true;particleMain.startSize=.4f;particleMain.startLifetime=2;particleMain.startSpeed=0;particleMain.startColor=Color.white;particleMain.gravityModifier=0;var shape=particle.shape;shape.enabled=false;var emission=particle.emission;emission.enabled=true;emission.rateOverTime=20;particleMaterial=new Material(Shader.Find("UI/Default"));particleMaterial.name=particleTemplate.GetComponent<ParticleSystemRenderer>().sharedMaterial.name;particleGo.GetComponent<ParticleSystemRenderer>().sharedMaterial=particleMaterial;particle.useAutoRandomSeed=false;particle.randomSeed=123;particle.Simulate(.1f,false,true,true);particle.Play(false);
            var cameraGo=new GameObject("Particle render comparison",typeof(Camera));SceneManager.MoveGameObjectToScene(cameraGo,scene);var camera=cameraGo.GetComponent<Camera>();camera.scene=scene;camera.enabled=false;camera.transform.position=new Vector3(0,0,-10);camera.orthographic=true;camera.orthographicSize=1;camera.cullingMask=1<<30;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;particleTarget=new RenderTexture(256,256,24);camera.targetTexture=particleTarget;
            Texture2D RenderParticle(string filename){camera.Render();var previous=RenderTexture.active;RenderTexture.active=particleTarget;var image=new Texture2D(256,256,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,256,256),0,0);image.Apply();RenderTexture.active=previous;File.WriteAllBytes("Logs/"+filename+".png",image.EncodeToPNG());return image;}
