            foreach(var cue in premiumCues){cue.Strike();cue.SetCharge(.8f);cue.UpdateGeometry(.7f);}
            text.text="2 : 7 승리했습니다";imageGo.transform.localPosition=new Vector3(70,90,0);elastic.tension=.8f;elastic.SetVerticesDirty();visual.side=1;visual.time=1;visual.counters[1].Displayed=7;hud.ApplyReplayVisual(JsonUtility.ToJson(visual));particle.Simulate(.5f,false,false,true);particle.Play(false);Canvas.ForceUpdateCanvases();capture.Capture(scene,null,1);report.captureMs=capture.LastMilliseconds;report.changes=capture.ChangeCount;
            Check(data.textures.Count==0&&data.meshes.Count==0&&data.materials.Count==0,"Gameplay capture contains no PNG, GPU mesh or compressed display blobs");
            capture.CompleteAssets();var memory=new MemoryStream();using(var writer=new BinaryWriter(memory,System.Text.Encoding.UTF8,true))data.Write(writer);memory.Position=0;MatchReplayPresentation loaded;using(var reader=new BinaryReader(memory))loaded=MatchReplayPresentation.Read(reader,data.frames.Count);
            particleReference=RenderParticle("replay-state-particle-source");
            Check(loaded.presentationVersion==MatchReplayStateCapture.Format&&loaded.winner==1&&loaded.result=="승리","State-event archive preserves final result");
            var viewer=new GameObject("Viewer");SceneManager.MoveGameObjectToScene(viewer,scene);display=new MatchReplayStateDisplay(viewer.transform,loaded,null);display.Apply(2);Canvas.ForceUpdateCanvases();
            var replayCues=display.Root.GetComponentsInChildren<PremiumCueWorld>(true);Check(replayCues.Length==3&&replayCues.All(c=>!c.enabled),"Premium cues replay as visual-only components");foreach(var source in premiumCues){var expected=source.CaptureReplayState();var replay=replayCues.Single(c=>c.CaptureReplayState().style==expected.style);Check(replay.CaptureReplayState().time==expected.time&&replay.CaptureReplayState().charge==expected.charge&&replay.GetComponentsInChildren<MeshFilter>(true).Zip(source.GetComponentsInChildren<MeshFilter>(true),(a,b)=>a.sharedMesh.vertices.SequenceEqual(b.sharedMesh.vertices)&&a.sharedMesh.colors32.SequenceEqual(b.sharedMesh.colors32)&&a.sharedMesh.triangles.SequenceEqual(b.sharedMesh.triangles)).All(same=>same),"Premium cue body and animated effects preserve charge, clock and geometry: "+expected.style);}
            var replayText=display.Root.GetComponentsInChildren<TMP_Text>(true).Single();Check(replayText.text=="2 : 7 승리했습니다","Final score/result text replay");
