            Check(replayText.transform.parent is RectTransform replayLayout&&replayLayout.sizeDelta==layout.sizeDelta&&replayLayout.anchorMin==layout.anchorMin&&replayLayout.anchoredPosition==layout.anchoredPosition,"Non-graphic UI layout parents retain RectTransform anchors, dimensions and offset");
            Check(display.Root.GetComponentsInChildren<Button>(true).Length==0,"Replay contains no interactive or game components");
            Check(Mathf.Approximately(display.Root.GetComponentInChildren<ElasticControlGraphic>(true).tension,.8f),"Cue UI parameters replay without copying its vertices");
            Check(display.Root.GetComponentInChildren<MatchHudView>(true).ActiveSide==1&&display.Root.GetComponentInChildren<MatchHudView>(true).Counters[1].Displayed==7,"HUD turn/score/effect clock replay");
            Check(display.Root.GetComponentInChildren<ParticleSystem>(true).randomSeed==123&&Mathf.Abs(display.Root.GetComponentInChildren<ParticleSystem>(true).time-particle.time)<.05f,"Particle effect seed and clock replay without baked meshes");
            var sourceParticles=new ParticleSystem.Particle[particle.main.maxParticles];var replayParticles=new ParticleSystem.Particle[particle.main.maxParticles];int sourceCount=particle.GetParticles(sourceParticles),replayCount=display.Root.GetComponentInChildren<ParticleSystem>(true).GetParticles(replayParticles);
            Check(sourceCount==replayCount&&Enumerable.Range(0,sourceCount).All(i=>Vector3.Distance(sourceParticles[i].position,replayParticles[i].position)<.001f),$"Seeded particle positions survive state replay: source={sourceCount}, replay={replayCount}, sourceTime={particle.time}, replayTime={display.Root.GetComponentInChildren<ParticleSystem>(true).time}, emitting={particle.isEmitting}, firstSource={(sourceCount>0?sourceParticles[0].position:Vector3.zero)}, firstReplay={(replayCount>0?replayParticles[0].position:Vector3.zero)}");
            var particleReplay=RenderParticle("replay-state-particle-replayed");var pixels=particleReference.GetPixels32();var actualPixels=particleReplay.GetPixels32();long difference=0,light=0;for(int i=0;i<pixels.Length;i++){light+=pixels[i].r+pixels[i].g+pixels[i].b;difference+=Math.Abs(pixels[i].r-actualPixels[i].r)+Math.Abs(pixels[i].g-actualPixels[i].g)+Math.Abs(pixels[i].b-actualPixels[i].b);}UnityEngine.Object.DestroyImmediate(particleReplay);Check(light>1000&&difference/(double)(pixels.Length*765)<.01,"Recorded particles render with the same layer, material, size and color");
            display.Apply(0);Check(replayText.text=="0 : 0","Seeking backwards restores HUD");display.Apply(2);Check(replayText.text.Contains("승리"),"Seeking forwards restores result");
